#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<long long> a(n);
    for (auto &v : a) cin >> v;
    // L[i] / R[i]: nearest strictly higher position on each side (monotone stacks).
    vector<int> L(n, -1), R(n, n), st;
    for (int i = 0; i < n; i++) {
        while (!st.empty() && a[st.back()] <= a[i]) st.pop_back();
        if (!st.empty()) L[i] = st.back();
        st.push_back(i);
    }
    st.clear();
    for (int i = n - 1; i >= 0; i--) {
        while (!st.empty() && a[st.back()] <= a[i]) st.pop_back();
        if (!st.empty()) R[i] = st.back();
        st.push_back(i);
    }
    long long total = 0;
    for (int i = 0; i < n; i++) total += R[i] - L[i] - 1;
    cout << total << "\n";
}

import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static long nextLong() {
        while (buf[pos] <= ' ') pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return r;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = (int) nextLong();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        // L[i] / R[i]: nearest strictly higher position on each side (monotone stacks).
        int[] L = new int[n], R = new int[n], st = new int[n];
        int top = 0;
        for (int i = 0; i < n; i++) {
            while (top > 0 && a[st[top - 1]] <= a[i]) top--;
            L[i] = top > 0 ? st[top - 1] : -1;
            st[top++] = i;
        }
        top = 0;
        for (int i = n - 1; i >= 0; i--) {
            while (top > 0 && a[st[top - 1]] <= a[i]) top--;
            R[i] = top > 0 ? st[top - 1] : n;
            st[top++] = i;
        }
        long total = 0;
        for (int i = 0; i < n; i++) total += R[i] - L[i] - 1;
        System.out.println(total);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(in, &n)
	a := make([]int64, n)
	for i := range a {
		fmt.Fscan(in, &a[i])
	}
	// L[i] / R[i]: nearest strictly higher position on each side (monotone stacks).
	L := make([]int, n)
	R := make([]int, n)
	st := []int{}
	for i := 0; i < n; i++ {
		for len(st) > 0 && a[st[len(st)-1]] <= a[i] {
			st = st[:len(st)-1]
		}
		L[i] = -1
		if len(st) > 0 {
			L[i] = st[len(st)-1]
		}
		st = append(st, i)
	}
	st = st[:0]
	for i := n - 1; i >= 0; i-- {
		for len(st) > 0 && a[st[len(st)-1]] <= a[i] {
			st = st[:len(st)-1]
		}
		R[i] = n
		if len(st) > 0 {
			R[i] = st[len(st)-1]
		}
		st = append(st, i)
	}
	var total int64
	for i := 0; i < n; i++ {
		total += int64(R[i] - L[i] - 1)
	}
	fmt.Println(total)
}
